import numpy as np

def flag_readings(readings, offsets, limit):
    r = np.asarray(readings)
    o = np.asarray(offsets)
    if r.ndim != 2:
        raise ValueError('readings phải có hai chiều')
    if o.ndim != 1 or o.shape[0] != r.shape[1]:
        raise ValueError('offsets phải có một giá trị cho mỗi cột')
    if not np.issubdtype(r.dtype, np.number) or not np.issubdtype(o.dtype, np.number):
        raise TypeError('readings và offsets phải là dữ liệu số')
    if not np.isfinite(r).all() or not np.isfinite(o).all() or not np.isfinite(limit):
        raise ValueError('đầu vào phải hữu hạn')
    corrected = r - o
    return corrected > limit
Các bước: (1) chuyển đầu vào thành mảng và xác thực số chiều, độ dài; (2) từ chối giá trị không phải số hoặc không hữu hạn theo chính sách ví dụ; (3) trừ offsets shape (số_cảm_biến,) khỏi từng hàng bằng broadcasting; (4) so ngưỡng để trả mảng boolean. Broadcasting tránh vòng lặp Python và diễn đạt phép tính theo cột, nhưng cần kiểm tra shape để tránh áp dụng sai độ lệch. Chính sách từ chối NaN/giá trị thiếu giúp không âm thầm xem kết quả so sánh là không cảnh báo; nếu nghiệp vụ muốn giữ giá trị thiếu, cần quy định đầu ra ba trạng thái thay vì chỉ boolean.

