import pandas as pd

def revenue_by_product(orders, products):
    required_orders = {'order_id', 'product_id', 'qty'}
    required_products = {'product_id', 'unit_price'}
    if not required_orders.issubset(orders.columns) or not required_products.issubset(products.columns):
        raise ValueError('Thiếu cột bắt buộc')
    if orders[['product_id', 'qty']].isna().any().any():
        raise ValueError('Đơn hàng thiếu product_id hoặc qty')
    if products[['product_id', 'unit_price']].isna().any().any():
        raise ValueError('Danh mục thiếu product_id hoặc unit_price')
    if products['product_id'].duplicated().any():
        raise ValueError('product_id trùng trong products')
    if not pd.api.types.is_numeric_dtype(orders['qty']) or not pd.api.types.is_numeric_dtype(products['unit_price']):
        raise ValueError('qty và unit_price phải là dữ liệu số')
    joined = orders.merge(
        products[['product_id', 'unit_price']],
        on='product_id', how='left', validate='many_to_one', indicator=True
    )
    if (joined['_merge'] != 'both').any():
        raise ValueError('Có đơn hàng không tìm được product_id trong products')
    joined['line_revenue'] = joined['qty'] * joined['unit_price']
    return joined.groupby('product_id', as_index=False)['line_revenue'].sum().rename(
        columns={'line_revenue': 'revenue'}
    )

Đối chiếu từng bước: kiểm tra cột và dữ liệu thiếu; kiểm tra khóa duy nhất ở products; left join với validate để tránh nhân bản giao dịch; dùng indicator tìm khóa không khớp; nhân qty với unit_price trên từng hàng rồi groupby/sum. Quyết định báo lỗi thay vì điền giá 0 ngăn báo cáo doanh thu thấp giả tạo. Đánh đổi là một đơn lỗi có thể chặn cả báo cáo; có thể tách hàng lỗi để xử lý riêng nếu nghiệp vụ cho phép. Rủi ro còn lại: mã này chưa kiểm tra qty âm, giá âm, đơn trùng order_id hay quy tắc làm tròn tiền; cần xác nhận chính sách nghiệp vụ trước khi dùng cho báo cáo tài chính.

Chọn loại đơn lỗi khỏi tổng theo vùng nhưng trả chúng riêng trong issues để đối soát, thay vì âm thầm gán vùng. Ví dụ:
import pandas as pd

def summarize_by_region(orders, customers):
    required_orders = {'order_id', 'customer_id', 'amount'}
    required_customers = {'customer_id', 'region'}
    if not required_orders.issubset(orders.columns) or not required_customers.issubset(customers.columns):
        raise ValueError('Thiếu cột bắt buộc')
    if customers['customer_id'].isna().any() or customers['customer_id'].duplicated().any():
        raise ValueError('customer_id trong customers phải có và duy nhất')
    if orders['order_id'].isna().any() or orders['order_id'].duplicated().any():
        raise ValueError('order_id trong orders phải có và duy nhất')
    data = orders.copy()
    data['amount'] = pd.to_numeric(data['amount'], errors='coerce')
    data = data.merge(customers[['customer_id', 'region']], on='customer_id', how='left', validate='many_to_one', indicator=True)
    bad = data['customer_id'].isna() | data['region'].isna() | data['amount'].isna() | (data['amount'] < 0)
    issues = data.loc[bad].copy()
    summary = (data.loc[~bad].groupby('region', as_index=False)['amount'].sum().rename(columns={'amount': 'total_amount'}))
    return summary, issues
Có thể dùng cột _merge trong issues để phân biệt khách không khớp với khách có region thiếu. Việc tách issues giữ báo cáo tổng theo vùng diễn giải được, nhưng tổng summary sẽ thấp hơn tổng các đơn đầu vào cho tới khi xử lý lỗi; cần công bố số và giá trị đơn bị loại. Khóa khách trùng có thể nhân dòng, làm tăng giả doanh thu, nên hàm kiểm tra trước và validate khi ghép. Nếu nghiệp vụ cho phép order_id trùng, phải xác định lại đơn vị quan sát trước khi áp dụng kiểm tra đó.

Tạm hoãn phương án tự động gửi danh sách cho tất cả giảng viên; chỉ thử nghiệm trong phạm vi nhóm hỗ trợ được phân quyền sau khi đánh giá và phê duyệt. Bước 1: xác định mục đích là đề xuất hỗ trợ, không phải kết luận sinh viên yếu kém; kiểm tra bằng chứng đằng sau ngưỡng 'nguy cơ cao', tỷ lệ gắn cờ sai và kết quả theo nhóm học toàn thời gian/bán thời gian, có xét các yếu tố liên quan trước khi quy chênh lệch cho một nguyên nhân. Bước 2: rà soát dữ liệu đầu vào; loại thông tin liên hệ và chi tiết sức khỏe khỏi dữ liệu đưa vào mô hình nếu không cần thiết, hạn chế dùng ghi chú tự do, quy định thời hạn lưu và người được truy cập. Bước 3: giao nhóm hỗ trợ chịu trách nhiệm xem xét; AI chỉ tạo gợi ý, người phụ trách đối chiếu thông tin phù hợp, có thể bác bỏ và ghi lý do trước khi liên hệ riêng với sinh viên. Bước 4: thông báo rõ cho người liên quan rằng AI được dùng để gợi ý hỗ trợ, nêu giới hạn, đầu mối hỏi đáp và cách đề nghị sửa thông tin; không công bố nhãn 'nguy cơ cao' rộng rãi. Bước 5: theo dõi tỷ lệ sai và tác động theo nhóm, kiểm tra định kỳ quyền truy cập, tiếp nhận phản hồi và dừng quy trình nếu phát hiện tác hại đáng kể.
